void init() noexcept { api.library = dlopen("libserdes.so", RTLD_NOW | RTLD_LOCAL); if (api.library) api.path = "libserdes.so"; if (!api.library) { Dl_info info{}; if (dladdr(reinterpret_cast<const void*>(&init), &info) && info.dli_fname) { std::string_view path{info.dli_fname}; const auto slash = path.rfind('/'); if (slash != path.npos && slash + 13 < fallback.size()) { std::snprintf(fallback.data(), fallback.size(), "%.*s/libserdes.so", static_cast<int>(slash), path.data()); api.library = dlopen(fallback.data(), RTLD_NOW | RTLD_LOCAL); if (api.library) api.path = fallback.data(); } } } if (!api.library) { api.error = dlerror(); return; } bind(api.abi, "kserdes_abi_version"); bind(api.parse, "kryml_document_parse"); bind(api.destroy, "kryml_document_destroy"); bind(api.format, "kryml_document_format"); bind(api.json, "kryml_document_json"); bind(api.valid, "kryml_valid"); bind(api.json_to_yaml, "kryml_json_to_yaml"); bind(api.root, "kryml_document_root"); bind(api.key, "kryml_node_key"); bind(api.index, "kryml_node_index"); bind(api.parent, "kryml_node_parent"); bind(api.type, "kryml_node_type"); bind(api.size, "kryml_node_size"); bind(api.key_view, "kryml_node_key_view"); bind(api.value_view, "kryml_node_value_view"); bind(api.set_value, "kryml_node_set_value"); bind(api.append, "kryml_map_append"); bind(api.remove, "kryml_node_remove"); if (!api.ready()) api.error = "missing required serdes rapidyaml symbols"; }
