{ size_t size{}; auto& a = instance(); const auto* value = *this && a.value_view ? a.value_view(document_, id_, &size) : nullptr; return value ? view_type{value, size} : view_type{}; } bool Node::set_value(view_type value) noexcept { auto& a = instance(); return *this && a.set_value && a.set_value(document_, id_, value.data(), value.size()) == 0; } Node Node::append(view_type key, view_type value) noexcept { auto& a = instance(); return {document_, *this && a.append ? a.append(document_, id_, key.data(), key.size(), value.data(), value.size()) : none}; } bool Node::erase() noexcept { auto& a = instance(); if (!*this || !a.remove || a.remove(document_, id_) != 0) return false; id_ = none; return true; } bool loaded() noexcept { return instance().ready(); } uint32_t abi_version() noexcept { auto& a = instance(); return a.abi ? a.abi() : 0; } std::string_view library_path() noexcept { auto& a = instance(); return a.path ? a.path : ""; } std::string_view load_error() noexcept { auto& a = instance(); return a.error ? a.error : ""; } bool valid(view_type input) noexcept { auto& a = instance(); return a.valid && a.valid(input.data(), input.size()) != 0; } size_t json_to_yaml(view_type input, std::span<char> output) noexcept { size_t size{}; auto& a = instance(); return a.json_to_yaml ? (a.json_to_yaml(input.data(), input.size(), output.data(), output.size(), &size), size) : 0; }
